 subsetvary=len({g['accuracy'] for g in valid})>1;equalover=len({g['overlong'] for g in grades})==1;zero=max(g['total'] for g in grades)-min(g['total'] for g in grades)<=1e-12
 reasons={'zero_total_reward_variance':zero,'no_overall_accuracy_variation':not vary,'no_full_format_valid_subset_accuracy_variation':not subsetvary,'not_all_four_full_format':len(valid)!=4,'varying_overlong_penalty':not equalover}
