def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--primary-root',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--private-output',type=Path,required=True);a=p.parse_args();W=Path(__file__).resolve().parents[1];R=a.primary_root.resolve();require(a.output.resolve().is_relative_to(W/'results') and a.private_output.resolve().is_relative_to(W/'local_data'),'Own V2 destinations only');require(not a.output.exists() and not a.private_output.exists(),'Preserve immutable analysis; choose new version')
