  lengths=[len(v['token_ids']) for v in raw['responses']];require(all(v['generation_tokens']==n and n<=256 for v,n in zip(raw['responses'],lengths)),'Actual token lengths inconsistent');profile=grade_profile(receipt['grades'],lengths);require(receipt['updated']==profile['adaptive_eligible'],'Reconstructed eligibility differs');require(receipt['optimizer_updates']==previous_updates+int(receipt['updated']) and receipt['absolute_optimizer_updates']==52+receipt['optimizer_updates'],'Actual Adam cursor differs');previous_updates=receipt['optimizer_updates'];inputs=4*len(ids[0]);generated=sum(lengths);total=inputs+generated
